def main():
    if not pathlib.Path("scripts").is_dir():
        sys.exit("childharvest_tiles: run from the culprits-tiles-more repository root")
    for name, data in FILES.items():
        f = pathlib.Path(name)
        f.parent.mkdir(exist_ok=True)
        if f.exists() and f.read_text(encoding="utf-8") == data:
            print(f"childharvest_tiles: {name} already there")
            continue
        f.write_text(data, encoding="utf-8")
        print(f"childharvest_tiles: wrote {name}")


if __name__ == "__main__":
    main()
